package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string
var WsBigTotal decimal.Decimal
var WsWrapTotal decimal.Decimal
var WsSafeTotal decimal.Decimal
var WsOverflows int64
var WsCount int64
var WsHalf decimal.Decimal
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtFile *os.File
var amtScanner *bufio.Scanner
var curRec AmtRec
var eof bool

func pow10Int(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func pow10Dec(n int) decimal.Decimal {
	return decimal.New(pow10Int(n), 0)
}

// max for PIC 9(n)Vm
func maxVal(n, m int) decimal.Decimal {
	total := n + m
	p := pow10Int(total) // fits in int64 for these sizes
	return decimal.New(p-1, int32(-m))
}

func truncateToScale(v decimal.Decimal, scale int32) decimal.Decimal {
	return v.Truncate(scale)
}

// wrap storing val into PIC 9(n)Vm : keep low-order digits (mod 10^(n+m))
func wrapStore(val decimal.Decimal, n, m int) decimal.Decimal {
	neg := val.IsNegative()
	av := val.Abs()
	scaled := av.Shift(int32(m)).Truncate(0) // integer cents
	modPow := pow10Int(n + m)
	mod := decimal.New(modPow, 0)
	// scaled % mod
	rem := scaled.Mod(mod)
	res := rem.Shift(int32(-m))
	if neg {
		res = res.Neg()
	}
	// ensure scale m (trailing zeros)
	res = truncateToScale(res, int32(m))
	return res
}

func isOverflow(val decimal.Decimal, n, m int) bool {
	if val.IsNegative() {
		return true
	}
	mx := maxVal(n, m)
	// COBOL overflow is if integer digits exceed n
	// equivalent to val > max
	return val.GreaterThan(mx)
}

// ADD without SIZE ERROR : wraps on overflow
func addWrap(target decimal.Decimal, addend decimal.Decimal, n, m int) decimal.Decimal {
	sum := target.Add(addend)
	sum = truncateToScale(sum, int32(m))
	if isOverflow(sum, n, m) {
		return wrapStore(sum, n, m)
	}
	return sum
}

// ADD with SIZE ERROR : leaves unchanged on overflow, returns flag
func addSafe(target decimal.Decimal, addend decimal.Decimal, n, m int) (decimal.Decimal, bool) {
	sum := target.Add(addend)
	sum = truncateToScale(sum, int32(m))
	if isOverflow(sum, n, m) {
		return target, true
	}
	return sum, false
}

func formatEdited(val decimal.Decimal, picture string) string {
	// picture like "ZZ,ZZ9.99" or "ZZ,ZZ9.9"
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	var decDigits int
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
		decDigits = len(fracPic)
	} else {
		intPic = picture
		decDigits = 0
	}
	// count integer placeholders
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	// obtain scaled modulus representation
	av := val.Abs()
	// compute integer/fraction after wrapping high digits (as stored value already wrapped, but for safety)
	// We need to apply picture overflow dropping as well: keep low intDigits digits
	// Do mod 10^(intDigits+decDigits) on scaled
	totalDigits := intDigits + decDigits
	var scaledMod decimal.Decimal
	if totalDigits > 0 {
		scaled := av.Shift(int32(decDigits)).Truncate(0)
		modPow := pow10Int(totalDigits)
		mod := decimal.New(modPow, 0)
		scaledMod = scaled.Mod(mod)
	} else {
		scaledMod = decimal.Zero
	}
	pow10DecFrac := pow10Int(decDigits)
	var intPartInt int64
	var fracPartInt int64
	if decDigits > 0 {
		divisor := decimal.New(pow10DecFrac, 0)
		intPartDec := scaledMod.Div(divisor).Truncate(0)
		intPartInt = intPartDec.IntPart()
		fracPartDec := scaledMod.Mod(divisor)
		fracPartInt = fracPartDec.IntPart()
	} else {
		intPartInt = scaledMod.IntPart()
		fracPartInt = 0
	}
	intStr := fmt.Sprintf("%0*d", intDigits, intPartInt)
	fracStr := ""
	if decDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", decDigits, fracPartInt)
	}

	// Build integer edited part according to picture
	var outInt strings.Builder
	digitIdx := 0
	suppressed := true
	for _, ch := range intPic {
		if ch == ',' {
			if suppressed {
				outInt.WriteByte(' ')
			} else {
				outInt.WriteByte(',')
			}
		} else if ch == 'Z' || ch == '9' {
			d := intStr[digitIdx]
			digitIdx++
			if ch == 'Z' {
				if suppressed && d == '0' {
					// Check if all remaining integer digits are zero and the remaining placeholders are? Actually we want to suppress all leading zeros for Z.
					// If this is a Z and digit zero while still suppressed, output space.
					// But need to look ahead: if all remaining digits are zero and there is a trailing 9 that will provide the zero, we still suppress.
					// So simply suppress.
					outInt.WriteByte(' ')
				} else {
					outInt.WriteByte(d)
					suppressed = false
				}
			} else { // '9'
				outInt.WriteByte(d)
				if d != '0' {
					suppressed = false
				}
			}
		}
	}
	result := outInt.String()
	if decDigits > 0 {
		result += "." + fracStr
	}
	// Handle sign (not needed for unsigned, but include)
	if val.IsNegative() && !val.IsZero() {
		// COBOL edited pictures without sign would maybe? ignore
		// Prepend minus if space exists
		// For now just prefix '-'
		// Try to replace leading space with '-'
		b := []byte(result)
		for i := 0; i < len(b); i++ {
			if b[i] == ' ' {
				// find first space from left that is not comma area? Simplified: put minus at first space
				// But not needed for this program (no negatives)
				break
			}
		}
		result = "-" + result
	}
	// Ensure exact picture width (should already)
	if len(result) < len(picture) {
		// pad left with spaces (should not happen)
		result = strings.Repeat(" ", len(picture)-len(result)) + result
	}
	if len(result) > len(picture) {
		result = result[len(result)-len(picture):]
	}
	return result
}

func formatUneditedCount(v int64, digits int) string {
	// wrap already done, now zero-padded
	// v is modulo 10^digits
	if v < 0 {
		v = 0
	}
	mod := pow10Int(digits)
	v = v % mod
	return fmt.Sprintf("%0*d", digits, v)
}

func openAmtFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	amtFile = f
	amtScanner = bufio.NewScanner(f)
	// allow long lines
}

func readPara() {
	if amtScanner.Scan() {
		line := amtScanner.Text()
		// LINE SEQUENTIAL: record length 11, pad with spaces on right if shorter
		if len(line) < 11 {
			line = line + strings.Repeat(" ", 11-len(line))
		} else if len(line) > 11 {
			line = line[:11]
		}
		arAcct := line[0:4]
		arAmtStr := line[4:11]
		// arAmtStr is digits only, may contain spaces if line padded? But amount field should be digits.
		// Trim spaces, if empty treat as zero?
		trimmed := strings.TrimSpace(arAmtStr)
		// If line was short and padded, arAmtStr may contain spaces
		// Replace spaces with zeros? COBOL would have spaces padded -> reading as numeric may be zero? But spec says pad with spaces on right, amount field is at offset 4 len7, if line shorter than 11, padded spaces will be part of amount field.
		// In that case those spaces should be treated as zeros? For LINE SEQUENTIAL, short line padded with spaces means missing chars are spaces; numeric field with spaces would be zero? However typical COBOL numeric DISPLAY with spaces is zero. We'll treat non-digit as zero.
		// Let's parse only digits: filter digits
		digits := ""
		for _, c := range arAmtStr {
			if c >= '0' && c <= '9' {
				digits += string(c)
			} else if c == ' ' {
				digits += "0"
			}
		}
		if digits == "" {
			digits = "0"
		}
		// ensure length 7
		if len(digits) < 7 {
			digits = strings.Repeat("0", 7-len(digits)) + digits
		} else if len(digits) > 7 {
			digits = digits[len(digits)-7:]
		}
		// parse as integer
		n := int64(0)
		for _, c := range digits {
			n = n*10 + int64(c-'0')
		}
		// scale 2
		curRec = AmtRec{
			ArAcct: arAcct,
			ArAmt:  decimal.New(n, -2),
		}
		eof = false
		// set flag N
		WsEofFlag = "N"
	} else {
		eof = true
		WsEofFlag = "Y"
	}
}

func mainPara() {
	openAmtFile()
	// init working storage defaults already zero
	WsEofFlag = "N"
	WsBigTotal = decimal.New(0, -2)
	WsWrapTotal = decimal.New(0, -2)
	WsSafeTotal = decimal.New(0, -2)
	WsOverflows = 0
	WsCount = 0
	WsHalf = decimal.New(0, -1)

	readPara()
	for !eof {
		processPara()
	}
	if amtFile != nil {
		amtFile.Close()
	}
	summaryPara()
}

func readParaFunc() {
	readPara()
}

func processPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = addWrap(WsBigTotal, curRec.ArAmt, 7, 2)
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = wrapStore(WsBigTotal, 5, 2)
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	newSafe, overflow := addSafe(WsSafeTotal, curRec.ArAmt, 5, 2)
	if overflow {
		overflowPara()
	} else {
		WsSafeTotal = newSafe
	}
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100
	// COMPUTE WS-HALF = AR-AMT / 2  (truncated)
	half := curRec.ArAmt.Div(decimal.New(2, 0))
	// Actually spec says avoid Div, but we use Div and truncate; alternative Shift not for /2
	WsHalf = half.Truncate(1)
	// Check overflow for half (wrap if needed)
	if isOverflow(WsHalf, 5, 1) {
		WsHalf = wrapStore(WsHalf, 5, 1)
	}
	// MOVE to edited
	WsAmtEd = formatEdited(curRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
	fmt.Printf("%s %s %s %s %s\n", curRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	readParaFunc()
}

func summaryPara() {
	// DISPLAY "RECORDS: " WS-COUNT  (PIC 99 zero-padded)
	wsCountStr := formatUneditedCount(WsCount, 2)
	fmt.Printf("RECORDS: %s\n", wsCountStr)
	wsOverStr := formatUneditedCount(WsOverflows, 2)
	fmt.Printf("OVERFLOWS: %s\n", wsOverStr)
}

func overflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func main() {
	mainPara()
	_ = strings.Contains
	_ = trimmedHelper
}

func trimmedHelper(s string) string { return strings.TrimSpace(s) }

var _ = decimal.Zero

